-- =============================================================================
--  ARAC 01 — Equipo y habilidades de inicio correctos para todas las razas
--
--  Origen: pull request #42 de heyitsbench/mod-arac ("Fix starting gear and
--  skills", TRPB, 2025-08-19), ABIERTO y SIN MERGEAR en el upstream.
--  https://github.com/heyitsbench/mod-arac/pull/42
--  Corrige los issues #40 (falta equipo inicial) y #35.
--
--  Qué hace: en vez de depender de que copies a mano los .dbc del repo al
--  directorio dbc/ del servidor, vuelca esos tres DBC como tablas de override
--  en la BD del mundo. AzerothCore carga primero el fichero .dbc y luego
--  superpone la tabla homónima (ver LoadDBC en src/server/game/DataStores/
--  DBCStores.cpp), así que estas filas mandan sobre el fichero.
--
--  NOTA: de las tres tablas, el core solo lee charstartoutfit_dbc y
--  skillraceclassinfo_dbc. CharBaseInfo.dbc no lo carga el servidor (es de
--  cliente, para la pantalla de creación de personaje), así que
--  charbaseinfo_dbc queda como documentación y paridad con el upstream.
--
--  Idempotente: las tablas se recrean enteras (DROP + CREATE + INSERT).
-- =============================================================================

DROP TABLE IF EXISTS `charbaseinfo_dbc`; 
CREATE TABLE `charbaseinfo_dbc` ( `ID` INT NOT NULL DEFAULT '0', `RaceID` TINYINT UNSIGNED NOT NULL DEFAULT '0', `ClassID` TINYINT UNSIGNED NOT NULL DEFAULT '0', PRIMARY KEY (`ID`)) ENGINE=MyISAM DEFAULT CHARSET=utf8; 


