FAULT '0', `DisplayItemID_20` INT NOT NULL DEFAULT '0', `DisplayItemID_21` INT NOT NULL DEFAULT '0', `DisplayItemID_22` INT NOT NULL DEFAULT '0', `DisplayItemID_23` INT NOT NULL DEFAULT '0', `DisplayItemID_24` INT NOT NULL DEFAULT '0', `InventoryType_1` INT NOT NULL DEFAULT '0', `InventoryType_2` INT NOT NULL DEFAULT '0', `InventoryType_3` INT NOT NULL DEFAULT '0', `InventoryType_4` INT NOT NULL DEFAULT '0', `InventoryType_5` INT NOT NULL DEFAULT '0', `InventoryType_6` INT NOT NULL DEFAULT '0', `InventoryType_7` INT NOT NULL DEFAULT '0', `InventoryType_8` INT NOT NULL DEFAULT '0', `InventoryType_9` INT NOT NULL DEFAULT '0', `InventoryType_10` INT NOT NULL DEFAULT '0', `InventoryType_11` INT NOT NULL DEFAULT '0', `InventoryType_12` INT NOT NULL DEFAULT '0', `InventoryType_13` INT NOT NULL DEFAULT '0', `InventoryType_14` INT NOT NULL DEFAULT '0', `InventoryType_15` INT NOT NULL DEFAULT '0', `InventoryType_16` INT NOT NULL DEFAULT '0', `InventoryType_17` INT NOT NULL DEFAULT '0', `InventoryType_18` INT NOT NULL DEFAULT '0', `InventoryType_19` INT NOT NULL DEFAULT '0', `InventoryType_20` INT NOT NULL DEFAULT '0', `InventoryType_21` INT NOT NULL DEFAULT '0', `InventoryType_22` INT NOT NULL DEFAULT '0', `InventoryType_23` INT NOT NULL DEFAULT '0', `InventoryType_24` INT NOT NULL DEFAULT '0', PRIMARY KEY (`ID`)) ENGINE=MyISAM DEFAULT CHARSET=utf8; 

DROP TABLE IF EXISTS `skillraceclassinfo_dbc`; 
CREATE TABLE `skillraceclassinfo_dbc` ( `ID` INT NOT NULL DEFAULT '0', `SkillID` INT NOT NULL DEFAULT '0', `RaceMask` INT NOT NULL DEFAULT '0', `ClassMask` INT NOT NULL DEFAULT '0', `Flags` INT NOT NULL DEFAULT '0', `MinLevel` INT NOT NULL DEFAULT '0', `SkillTierID` INT NOT NULL DEFAULT '0', `SkillCostIndex` INT NOT NULL DEFAULT '0', PRIMARY KEY (`ID`)) ENGINE=MyISAM DEFAULT CHARSET=utf8; 
